; The Pokedex menu (2026-11-03, Pokedex forms Checkpoint D, "split by kind").
;
; One list of every identity, in data/pokemon/dex_display_rows.asm's order
; (generated by tools/gen_dex_display_rows.py):
;   - species rows, numbered as before (1..NUM_POKEMON);
;   - each regional form directly after its base species, with no number;
;   - the species stored as forms (Espeon, Perrserker, Clodsire...) at the end,
;     numbered NUM_POKEMON + 1 onward.
; The side menu (DATA / CRY / MOVE / QUIT) acts on whichever kind the row is:
; a species gets the ordinary page (predef ShowPokedexData, bank $10) and move
; viewer; a form gets FormDexShowData below and PokedexFormMoveViewer.
;
; Moved here from engine/menus/pokedex.asm (bank $10, which had 3 bytes left):
; ShowPokedexMenu is still reached by `predef ShowPokedexMenu`.
;
; RAM: none new. The list is 303 rows, past 8 bits, so the first visible row
; and the row count live in a 4-byte frame on the stack for the menu's lifetime
; (only the top-level loop touches it). wListScrollOffset keeps its old
; contract: saved on entry, restored on exit, for the other list menus.

DEF DEX_LIST_ROWS EQU 7

ShowPokedexMenu::
	call GBPalWhiteOut
	call ClearScreen
	call UpdateSprites
	ld a, [wListScrollOffset]
	push af
	xor a
	ldh [hCurrentMenuItem], a
	ld [wListScrollOffset], a
	ld [wLastMenuItem], a
	inc a
	ld [wPokedexNum], a
	ldh [hJoy7], a
	call DexListRowCount ; hl = rows shown (last seen row + 1)
	push hl              ; frame +2: row count
	ld hl, 0
	push hl              ; frame +0: first visible row
.setUpGraphics
	ld b, SET_PAL_GENERIC
	call RunPaletteCommand
	callfar LoadPokedexTilePatterns
	call DexListDrawFrame
.loop
	call .frame          ; de = first row, bc = row count
	call DexListDrawRows ; a = rows drawn
	dec a
	ld hl, wTopMenuItemY
	ld [hl], 3           ; top menu item Y
	inc hl
	ld [hl], 0           ; top menu item X
	inc hl
	inc hl               ; wTileBehindCursor
	ld [hli], a          ; max menu item ID
	ld [hl], PAD_LEFT | PAD_RIGHT | PAD_B | PAD_A
	ld a, 1
	ld [wMenuWatchMovingOutOfBounds], a
	call HandleMenuInput
	bit B_PAD_B, a
	jp nz, .exit
	bit B_PAD_UP, a
	jr nz, .up
	bit B_PAD_DOWN, a
	jr nz, .down
	bit B_PAD_RIGHT, a
	jr nz, .pageDown
	bit B_PAD_LEFT, a
	jr nz, .pageUp
	; A: the side menu for the chosen row
	call .frame
	ldh a, [hCurrentMenuItem]
	add e
	ld e, a
	jr nc, .rowReady
	inc d
.rowReady
	call DexListSideMenu ; b: 0 = a screen was shown, 1 = QUIT, 2 = back
	dec b
	jr z, .exit
	dec b
	jr z, .loop
	jp .setUpGraphics

.up
	call .frame
	ld a, d
	or e
	jr z, .loop
	dec de
	jr .store
.down
	call .frame
	call .lastFirstRow   ; hl = the largest first row
	inc de
	call .clampDown
	jr .store
.pageDown
	call .frame
	call .lastFirstRow
	ld a, e
	add DEX_LIST_ROWS
	ld e, a
	jr nc, .pageDownClamp
	inc d
.pageDownClamp
	call .clampDown
	jr .store
.pageUp
	call .frame
	ld a, e
	sub DEX_LIST_ROWS
	ld e, a
	jr nc, .store
	dec d
	bit 7, d
	jr z, .store
	ld de, 0
.store ; de -> frame +0
	ld hl, sp+0
	ld [hl], e
	inc hl
	ld [hl], d
	jp .loop

.exit
	add sp, 4
	xor a
	ld [wMenuWatchMovingOutOfBounds], a
	ldh [hCurrentMenuItem], a
	ld [wLastMenuItem], a
	ldh [hJoy7], a
	ld [wOverrideSimulatedJoypadStatesMask], a
	pop af
	ld [wListScrollOffset], a
	call GBPalWhiteOutWithDelay3
	call RunDefaultPaletteCommand
	jp ReloadMapData

; Reads the frame. Called from the loop, so the frame sits 2 bytes further up.
; OUT: de = first visible row, bc = row count. Clobbers hl.
.frame
	ld hl, sp+2
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
	ld a, [hli]
	ld c, a
	ld b, [hl]
	ret

; IN: bc = row count. OUT: hl = max(0, rows - DEX_LIST_ROWS), the last page's first row.
.lastFirstRow
	ld a, c
	sub DEX_LIST_ROWS
	ld l, a
	ld a, b
	sbc 0
	ld h, a
	ret nc
	ld hl, 0
	ret

; de = min(de, hl). Clobbers a.
.clampDown
	ld a, l
	sub e
	ld a, h
	sbc d
	ret nc
	ld d, h
	ld e, l
	ret

; OUT: hl = number of rows the list shows: the last SEEN row + 1 (at least 1),
; as the old list stopped at the highest seen Pokedex number.
DexListRowCount:
	ld de, NUM_DEX_IDENTITIES - 1
.loop
	push de
	ld b, 0 ; seen
	call DexRowFlag
	pop de
	jr nz, .found
	ld a, d
	or e
	jr z, .found ; nothing seen at all: one row of dashes
	dec de
	jr .loop
.found
	inc de
	ld h, d
	ld l, e
	ret

; IN: de = row. OUT: a = DEX_ROW_* kind (high byte), c = its value (low byte).
; CLOBBERS: hl
DexRowEntry:
	ld hl, DexDisplayRows
	add hl, de
	add hl, de
	ld a, [hli]
	ld c, a
	ld a, [hl]
	ret

; IN: de = row, b = 0 for SEEN, 1 for OWNED. OUT: nz if that flag is set.
; Preserves de. CLOBBERS: af, bc, hl
DexRowFlag:
	call DexRowEntry
	and a
	jr nz, .form
	dec c ; dex number -> bit
	ld hl, wPokedexSeen
	dec b
	jr nz, .test
	ld hl, wPokedexOwned
	jr .test
.form
	ld hl, wPokedexFormSeen
	dec b
	jr nz, .test
	ld hl, wPokedexFormOwned
.test
	jp FormDexTestBit

; IN: c = a species row's dex number (from DexRowEntry). Sets wPokedexNum
; (= wNamedObjectIndex) to the internal species index. CLOBBERS: all
DexSpeciesRowIndex:
	ld a, c
	ld [wPokedexNum], a
	predef PokedexToIndex
	ret

; Static parts: dividers, title, collection seen/owned, the side menu's items.
DexListDrawFrame:
	xor a
	ldh [hAutoBGTransferEnabled], a
	call ClearScreen
	hlcoord 15, 8
	ld a, '─'
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hli], a
	hlcoord 14, 0
	ld [hl], $71 ; vertical line tile
	hlcoord 14, 1
	call FormDexVerticalLine
	hlcoord 14, 9
	call FormDexVerticalLine
	hlcoord 1, 1
	ld de, FormDexTitleText
	call PlaceString
	hlcoord 16, 2
	ld de, FormDexSeenText
	call PlaceString
	hlcoord 16, 5
	ld de, FormDexOwnText
	call PlaceString
	hlcoord 16, 10
	ld de, FormDexMenuItemsText
	call PlaceString
	farcall DexCountCollection ; whole collection, 16-bit big-endian
	ld de, wDexRatingNumMonsSeen
	hlcoord 16, 3
	lb bc, 2, 3
	call PrintNumber
	ld de, wDexRatingNumMonsOwned
	hlcoord 16, 6
	lb bc, 2, 3
	jp PrintNumber

FormDexVerticalLine: ; DrawPokedexVerticalLine
	ld c, 9
	ld de, SCREEN_WIDTH
	ld a, $71
.loop
	ld [hl], a
	add hl, de
	xor 1 ; toggle between vertical line tile and box tile
	dec c
	jr nz, .loop
	ret

; IN: de = first row, bc = row count. Draws up to DEX_LIST_ROWS rows.
; OUT: a = rows drawn (1..DEX_LIST_ROWS)
DexListDrawRows:
	xor a
	ldh [hAutoBGTransferEnabled], a
	; rows to draw = min(DEX_LIST_ROWS, count - first)
	ld a, c
	sub e
	ld l, a
	ld a, b
	sbc d
	jr nz, .full
	ld a, l
	cp DEX_LIST_ROWS
	jr c, .some
.full
	ld a, DEX_LIST_ROWS
.some
	push af
	push de
	hlcoord 1, 2
	lb bc, 14, 13
	call ClearScreenArea
	pop de
	pop af
	push af
	ld b, a
	hlcoord 1, 3
.row
	push bc
	push de
	push hl
	call DexListDrawRow
	pop hl
	ld bc, 2 * SCREEN_WIDTH
	add hl, bc
	pop de
	inc de
	pop bc
	dec b
	jr nz, .row
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
	call Delay3
	call GBPalNormal
	pop af
	ret

; One row. IN: de = row, hl = the row's column 1 (name row; the number goes on
; the row above). CLOBBERS: all
DexListDrawRow:
	push hl
	push de
	; number: species -> its dex number; numbered form -> NUM_POKEMON + 1 + k
	call DexRowEntry
	cp HIGH(DEX_ROW_REGIONAL)
	jr z, .numberDone ; regional forms are unnumbered
	; Numbered forms run NUM_POKEMON + 1 = 253 up to 265, past a byte, so the
	; number is printed from 2 big-endian bytes. Scratch: wDexRatingText, the
	; tail of the 180-byte union member DexListDrawFrame's DexCountCollection
	; already owns while the Pokedex is open (nothing reads it until the next
	; count rewrites the member).
	ld b, 0
	and a
	ld a, c
	jr z, .haveNumber
	ld a, e
	sub LOW((DexDisplayRowsNumbered - DexDisplayRows) / 2) ; the first numbered row
	add LOW(NUM_POKEMON + 1)
	jr nc, .haveNumber
	inc b
.haveNumber
	ld hl, wDexRatingText
	ld [hl], b
	inc hl
	ld [hl], a
	pop de
	pop hl
	push hl
	push de
	ld bc, -SCREEN_WIDTH
	add hl, bc
	ld de, wDexRatingText
	lb bc, LEADING_ZEROES | 2, 3
	call PrintNumber
.numberDone
	pop de
	pop hl
	inc hl
	inc hl ; column 3: owned ball
	push hl
	push de
	ld b, 1
	call DexRowFlag
	pop de
	pop hl
	ld a, ' '
	jr z, .noBall
	ld a, $72 ; pokeball tile
.noBall
	ld [hli], a ; column 4: the name
	push hl
	push de
	ld b, 0
	call DexRowFlag
	pop de
	jr nz, .seen
	ld de, FormDexDashes
	jr .place
.seen
	call DexRowEntry
	and a
	jr nz, .formName
	call DexSpeciesRowIndex
	xor a
	ld [wFormContextSpecies], a
	call GetMonName
	jr .place
.formName
	ld e, c
	farcall DexFormKeyOf ; d = species, e = form
	ld a, d
	ld [wNamedObjectIndex], a
	ld [wFormContextSpecies], a
	ld a, e
	ld [wFormContextForm], a
	call GetMonName
	xor a
	ld [wFormContextSpecies], a ; never leave a context pending
.place
	pop hl
	jp PlaceString

; The side menu. IN: de = row. OUT: b = 0 a screen was shown (redraw it all),
; 1 = QUIT, 2 = back / the row is unseen. The list's cursor state is saved and
; restored, as HandlePokedexSideMenu did.
DexListSideMenu:
	push de
	ld b, 0
	call DexRowFlag
	pop de
	ld b, 2
	ret z ; unseen: nothing to show
	ldh a, [hCurrentMenuItem]
	push af
	ld a, [wLastMenuItem]
	push af
	push de ; the row
	call PlaceUnfilledArrowMenuCursor
	ld hl, wTopMenuItemY
	ld a, 10
	ld [hli], a ; top menu item Y
	ld a, 15
	ld [hli], a ; top menu item X
	xor a
	ldh [hCurrentMenuItem], a
	inc hl ; wTileBehindCursor
	ld a, 3
	ld [hli], a ; max menu item ID
	ld [hli], a ; watched keys: 3 = PAD_A | PAD_B
	xor a
	ld [hli], a ; old menu item ID
	ld [wMenuWatchMovingOutOfBounds], a
.input
	call HandleMenuInput
	bit B_PAD_B, a
	ld b, 2
	jr nz, .back
	ldh a, [hCurrentMenuItem]
	and a
	jr z, .data
	dec a
	jr z, .cry
	dec a
	jr z, .move
	ld b, 1 ; QUIT
	jr .done
.data
	pop de
	push de
	call DexRowEntry
	and a
	jr nz, .formData
	call DexSpeciesRowIndex
	predef ShowPokedexData ; the ordinary page, bank $10
	jr .shown
.formData
	call FormDexShowData ; c = identity id
	jr .shown
.cry ; a form cries as its base species
	pop de
	push de
	call DexRowSpecies ; a = internal species
	push af
	ld a, 1 ; play without waiting, as the old menu did
	ld [wSFXDontWait], a
	pop af
	call PlayCry
	xor a
	ld [wSFXDontWait], a
	jr .input
.move
	pop de
	push de
	call DexRowEntry
	and a
	jr nz, .formMove
	call DexSpeciesRowIndex
	ld a, [wPokedexNum]
	ld e, a
	farcall PokedexMoveViewer
	jr .shown
.formMove ; the form's own level-up and TM/HM lists
	ld e, c
	farcall DexFormKeyOf ; d = species, e = form
	ld a, d
	ld d, e
	ld e, a ; e = species, d = form
	farcall PokedexFormMoveViewer
.shown
	ld b, 0
	jr .done
.back
	push bc
	hlcoord 15, 10
	ld de, 20
	lb bc, ' ', 7
	call FormDexTileLine ; cover the side menu cursor
	pop bc
.done
	pop af ; the row
	pop af
	ld [wLastMenuItem], a
	pop af
	ldh [hCurrentMenuItem], a
	push bc
	hlcoord 0, 3
	ld de, 20
	lb bc, ' ', 13
	call FormDexTileLine ; cover the list cursor
	pop bc
	ret

; IN: de = row. OUT: a = the row's internal species (a form's base species).
DexRowSpecies:
	call DexRowEntry
	and a
	jr nz, .form
	call DexSpeciesRowIndex
	ld a, [wPokedexNum]
	ret
.form
	ld e, c
	farcall DexFormKeyOf
	ld a, d
	ret

; IN: hl = flag array, c = bit. OUT: nz if set. Preserves bc, de.
FormDexTestBit:
	push bc
	ld a, c
	srl a
	srl a
	srl a
	add l
	ld l, a
	jr nc, .noCarry
	inc h
.noCarry
	ld a, c
	and 7
	ld b, a
	inc b
	ld a, [hl]
.shift
	dec b
	jr z, .test
	rrca
	jr .shift
.test
	pop bc
	and 1
	ret

; Publish identity [wRewardInfoSlot] & $7F as the pending form context, for the
; next GetMonName or GetMonHeader (each consumes or ignores it). OUT: a = species.
FormDexPublish:
	ld a, [wRewardInfoSlot]
	and $7f
	ld e, a
	farcall DexFormKeyOf
	ld a, e
	ld [wFormContextForm], a
	ld a, d
	ld [wFormContextSpecies], a
	ret

; ---------------------------------------------------------------------------
; FormDexShowData: one identity's data page. IN: c = DEX_FORM_* id (seen).
; Follows ShowPokedexDataInternal (engine/menus/pokedex.asm) line for line where
; it can; differences are commented.
; ---------------------------------------------------------------------------
FormDexShowData:
	ld a, c
	or $80
	ld [wRewardInfoSlot], a ; form palette in SetPal_Pokedex; cleared on exit
	ld hl, wStatusFlags2
	set BIT_NO_AUDIO_FADE_OUT, [hl]
	ld a, $33 ; 3/7 volume
	ldh [rAUDVOL], a
	call GBPalWhiteOut ; zero all palettes
	call ClearScreen
	call FormDexPublish ; a = species
	xor a
	ld [wFormContextSpecies], a ; only the species is wanted here
	ld a, d
	ld [wCurPartySpecies], a
	ld [wPokedexNum], a
	ld b, SET_PAL_POKEDEX
	call RunPaletteCommand
	ldh a, [hTileAnimations]
	push af
	xor a
	ldh [hTileAnimations], a

	hlcoord 0, 0
	ld de, 1
	lb bc, $64, SCREEN_WIDTH
	call FormDexTileLine ; top border
	hlcoord 0, 17
	ld b, $6f
	call FormDexTileLine ; bottom border
	hlcoord 0, 1
	ld de, 20
	lb bc, $66, $10
	call FormDexTileLine ; left border
	hlcoord 19, 1
	ld b, $67
	call FormDexTileLine ; right border
	ld a, $63 ; upper left corner tile
	ldcoord_a 0, 0
	ld a, $65 ; upper right corner tile
	ldcoord_a 19, 0
	ld a, $6c ; lower left corner tile
	ldcoord_a 0, 17
	ld a, $6e ; lower right corner tile
	ldcoord_a 19, 17
	hlcoord 0, 9
	ld de, FormDexDividerLine
	call PlaceString
	hlcoord 9, 6
	ld de, FormDexHeightWeightText
	call PlaceString

	call FormDexPublish
	ld [wNamedObjectIndex], a
	call GetMonName
	xor a
	ld [wFormContextSpecies], a
	hlcoord 9, 2
	call PlaceString ; the form's name

	ld a, [wRewardInfoSlot]
	and $7f
	ld e, a
	ld d, 0
	ld hl, FormDexEntryPointers
	add hl, de
	add hl, de
	ld a, [hli]
	ld e, a
	ld d, [hl] ; de = this identity's entry
	hlcoord 9, 4
	call PlaceString ; category; de -> its terminator

	; № + the base species' Pokedex number (a form has no number of its own)
	push de
	ld a, [wCurPartySpecies]
	ld [wPokedexNum], a
	predef IndexToPokedex
	hlcoord 2, 8
	ld a, '№'
	ld [hli], a
	ld a, '<DOT>'
	ld [hli], a
	ld de, wPokedexNum
	lb bc, LEADING_ZEROES | 1, 3
	call PrintNumber
	ld a, [wCurPartySpecies]
	ld [wPokedexNum], a
	ld [wCurSpecies], a
	ld a, [wRewardInfoSlot]
	and $7f
	ld c, a
	ld hl, wPokedexFormOwned
	call FormDexTestBit
	pop de
	push af ; nz = owned

	push de
	call Delay3
	call GBPalNormal
	call FormDexPublish ; the form's sprite, types and base stats
	call GetMonHeader
	xor a
	ld [wFormContextSpecies], a
	hlcoord 1, 1
	call LoadFlippedFrontSpriteByMonIndex
	ld a, [wCurPartySpecies]
	call PlayCry
	pop de

	pop af
	jp z, .waitForButtonPress ; not owned: name and sprite only, as for a species
	inc de ; de = feet
	hlcoord 12, 6
	lb bc, 1, 2
	call PrintNumber ; feet
	ld a, '′'
	ld [hl], a
	inc de
	inc de ; de = inches
	hlcoord 15, 6
	lb bc, LEADING_ZEROES | 1, 2
	call PrintNumber ; inches
	ld a, '″'
	ld [hl], a
	; weight, stored little-endian in tenths of pounds
	inc de
	inc de
	inc de ; de = weight high byte
	push de
	ld hl, hDexWeight
	ld a, [hl]
	push af
	ld a, [de]
	ld [hli], a
	ld a, [hl]
	push af
	dec de
	ld a, [de]
	ld [hl], a
	ld de, hDexWeight
	hlcoord 11, 8
	lb bc, 2, 5
	call PrintNumber
	hlcoord 14, 8
	ldh a, [hDexWeight + 1]
	sub 10
	ldh a, [hDexWeight]
	sbc 0
	jr nc, .next
	ld [hl], '0' ; below 1.0 lb, a 0 before the decimal point
.next
	inc hl
	ld a, [hli]
	ld [hld], a ; make room for the decimal point
	ld [hl], '<DOT>'
	pop af
	ldh [hDexWeight + 1], a
	pop af
	ldh [hDexWeight], a
	pop hl
	inc hl ; hl = description text
	bccoord 1, 11
	ld a, %10
	ldh [hClearLetterPrintingDelayFlags], a
	call TextCommandProcessor
	xor a
	ldh [hClearLetterPrintingDelayFlags], a
.waitForButtonPress2
	call JoypadLowSensitivity
	ldh a, [hJoy5]
	and PAD_A | PAD_B
	jr z, .waitForButtonPress2
	ld a, SFX_PRESS_AB
	call PlaySound
	hlcoord 1, 11
	lb bc, 5, 18
	call ClearScreenArea ; below the sprite
	hlcoord 9, 4
	lb bc, 5, 10
	call ClearScreenArea ; category, height and weight
	ld c, 20
	call DelayFrames
	; page two: types and base stats, as the ordinary page draws them
	hlcoord 9, 4
	ld de, FormDexTypeText
	call PlaceString
	ld a, [wLoadedMon + MON_CATCH_RATE]
	push af
	xor a
	ld [wLoadedMon + MON_CATCH_RATE], a
	hlcoord 10, 6
	predef PrintMonType
	pop af
	ld [wLoadedMon + MON_CATCH_RATE], a
	call FormDexBaseStats
.waitForButtonPress
	call JoypadLowSensitivity
	ldh a, [hJoy5]
	and PAD_A | PAD_B
	jr z, .waitForButtonPress
	pop af
	ldh [hTileAnimations], a
	xor a
	ld [wRewardInfoSlot], a
	call GBPalWhiteOut
	call ClearScreen
	call RunDefaultPaletteCommand
	call LoadTextBoxTilePatterns
	ld a, %11100000 ; FadePal4's rOBP1 (see ShowPokedexDataInternal)
	ldh [rOBP1], a
	call GBPalNormal
	ld hl, wStatusFlags2
	res BIT_NO_AUDIO_FADE_OUT, [hl]
	ld a, $77 ; max volume
	ldh [rAUDVOL], a
	ret

; PrintBaseStats (engine/menus/pokedex.asm), for the header GetMonHeader loaded.
FormDexBaseStats:
	ldh a, [hUILayoutFlags]
	push af
	set BIT_SINGLE_SPACED_LINES, a
	ldh [hUILayoutFlags], a
	hlcoord 2, 11
	ld de, FormDexStatsText
	call PlaceString
	pop af
	ldh [hUILayoutFlags], a
	ld c, NUM_STATS
	hlcoord 10, 11
.loopStats
	push bc
	push hl
	ld a, NUM_STATS
	sub c
	ld c, a
	ld b, 0
	ld hl, wMonHBaseStats
	add hl, bc
	ld a, [hl]
	srl a
	cp $3f
	ld e, 0
	jr c, .lessThan128
	sub $3f
	ld e, 8
.lessThan128
	ld c, a
	pop hl
	ld b, 8
.loopFullTile
	ld a, c
	sub 8
	jr c, .partialTile
	ld c, a
	ld a, $48
	add e
	ld [hli], a
	dec b
	jr nz, .loopFullTile
	jr .done
.partialTile
	add 8 + $40
	add e
	ld [hli], a
	dec b
	jr z, .done
	ld a, $40
	add e
.loopEmptyTile
	ld [hli], a
	dec b
	jr nz, .loopEmptyTile
.done
	ld de, SCREEN_WIDTH - 8
	add hl, de
	pop bc
	dec c
	jr nz, .loopStats
	ret

FormDexTileLine: ; DrawTileLine: b = tile, c = count, de = step, hl = start
	push bc
	push de
.loop
	ld [hl], b
	add hl, de
	dec c
	jr nz, .loop
	pop de
	pop bc
	ret

FormDexTitleText:
	db "CONTENTS@"
FormDexSeenText:
	db "SEEN@"
FormDexOwnText:
	db "OWN@"
